cd .; python3 - <<'PY'
p='bench/heaps_test.adb'
s=open(p).read()

old="""      Test_Beap_Churn (N);
      Test_Weak_Churn (N);
      Test_Leftist_Churn (N);
   end loop;
"""
new="""      Test_Beap_Churn (N);
      Test_Weak_Churn (N);
      Test_Leftist_Churn (N);
      Test_Arena_Churn (N);
   end loop;
"""
assert s.count(old)==1
s=s.replace(old,new,1)

old2="""      Test_Weak (N);
      Test_Leftist (N);
"""
new2="""      Test_Weak (N);
      Test_Leftist (N);
      Test_Arena (N);
"""
assert s.count(old2)==1
s=s.replace(old2,new2,1)

old3="""   Test_Meld (0, 0, 2);
"""
new3="""   Test_Meld (0, 0, 2);

   --  The arena's own meld, over the same shapes. It gets a k-way fold as
   --  well: with one pool holding every operand, folding k trees into one is
   --  the workload the structure exists for, and it is the case a heap that
   --  owns its pool cannot run without copying.
   for N of Sizes loop
      Test_Arena_Meld (N, N);
      Test_Arena_Meld (N, 1);
      Test_Arena_Meld (1, N);
      Test_Arena_Meld (N, 0);
      Test_Arena_Meld (0, N);
      Test_Arena_KWay (N, 16);
   end loop;
   Test_Arena_Meld (0, 0);
   Test_Arena_KWay (1, 16);
"""
assert s.count(old3)==1
s=s.replace(old3,new3,1)
open(p,'w').write(s)
print("ok")
PY
gprbuild -P bench.gpr -q 2>&1 | head -40
